package com.example.autoswipe;
import android.accessibilityservice.*;import android.view.accessibility.*;import android.content.*;import android.graphics.*;import android.os.*;import android.provider.Settings;import android.view.*;import android.widget.*;
public class SwipeAccessibilityService extends AccessibilityService{
 public static SwipeAccessibilityService instance; Handler h=new Handler(Looper.getMainLooper());WindowManager wm;View overlay;boolean running;int token,done,max,interval,duration,direction;
 public void onAccessibilityEvent(AccessibilityEvent e){}public void onInterrupt(){stop();}
 protected void onServiceConnected(){super.onServiceConnected();instance=this;}
 public void onDestroy(){stop();instance=null;super.onDestroy();}
 public void start(){if(running)return;if(!Settings.canDrawOverlays(this))return;android.content.SharedPreferences p=getSharedPreferences("settings",0);max=p.getInt("count",100);interval=p.getInt("interval",3000);duration=p.getInt("duration",500);direction=p.getInt("direction",0);done=0;running=true;int t=++token;show();h.postDelayed(()->swipe(t),1500);}
 public void stop(){running=false;token++;h.removeCallbacksAndMessages(null);if(overlay!=null){try{wm.removeView(overlay);}catch(Exception e){}overlay=null;}}
 void swipe(int t){if(!running||t!=token)return;if(max>0&&done>=max){stop();return;}android.util.DisplayMetrics m=getResources().getDisplayMetrics();float x=m.widthPixels*.5f;Path p=new Path();p.moveTo(x,m.heightPixels*(direction==0?.78f:.3f));p.lineTo(x,m.heightPixels*(direction==0?.3f:.78f));GestureDescription g=new GestureDescription.Builder().addStroke(new GestureDescription.StrokeDescription(p,0,duration)).build();boolean ok=dispatchGesture(g,new GestureResultCallback(){public void onCompleted(GestureDescription g){if(!running||t!=token)return;done++;if(max>0&&done>=max){stop();return;}h.postDelayed(()->swipe(t),interval);}public void onCancelled(GestureDescription g){if(running&&t==token)h.postDelayed(()->swipe(t),interval);}},h);if(!ok)stop();}
 void show(){wm=(WindowManager)getSystemService(WINDOW_SERVICE);LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setBackgroundColor(0xff202b3c);TextView stop=new TextView(this);stop.setText("■ 停止滑动");stop.setTextColor(-1);stop.setTextSize(18);stop.setPadding(24,24,24,24);box.addView(stop);stop.setOnClickListener(v->stop());WindowManager.LayoutParams p=new WindowManager.LayoutParams(-2,-2,WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE,PixelFormat.TRANSLUCENT);p.gravity=Gravity.TOP|Gravity.LEFT;p.x=20;p.y=180;box.setOnTouchListener(new View.OnTouchListener(){float x,y;int ox,oy;public boolean onTouch(View v,MotionEvent e){if(e.getAction()==0){x=e.getRawX();y=e.getRawY();ox=p.x;oy=p.y;return true;}if(e.getAction()==1||e.getAction()==2){p.x=ox+(int)(e.getRawX()-x);p.y=oy+(int)(e.getRawY()-y);wm.updateViewLayout(box,p);return true;}return true;}});wm.addView(box,p);overlay=box;}
}